/**
 * Circuit tile geometry — single source of truth for both the tiled
 * background (src/lib/assets/circuit-pattern.svg, generated by src/lib/circuit/generate-svg.ts)
 * and the CircuitPulse animation, which walks this graph so pulses ride the
 * visible traces.
 *
 * Coordinates are in tile units; the tile is rendered at TILE_SIZE px, so
 * units map 1:1 to CSS pixels.
 *
 * Tiling rule: every trace that touches a tile edge must have a matching
 * trace at the same coordinate on the opposite edge so the pattern is one
 * continuous network. Ports: left/right at y ∈ {45, 140, 150, 160, 255},
 * top/bottom at x ∈ {60, 150, 240}. The generator script validates this.
 */

export const TILE_SIZE = 300;

export type Point = [number, number];

/** Polylines. Shared vertices between polylines become junctions. */
export const TRACES: Point[][] = [
  // Long horizontal run across the top with a shallow jog and taps
  [[0, 45], [30, 45], [60, 45], [80, 45], [90, 55], [120, 55], [150, 55], [170, 55], [180, 45], [240, 45], [300, 45]],

  // Three-trace bundle that jogs up together (differential-pair feel)
  [[0, 140], [75, 140], [100, 140], [115, 125], [150, 125], [200, 125], [215, 140], [240, 140], [300, 140]],
  [[0, 150], [105, 150], [120, 135], [195, 135], [210, 150], [300, 150]],
  [[0, 160], [75, 160], [110, 160], [125, 145], [150, 145], [190, 145], [205, 160], [240, 160], [300, 160]],

  // Long horizontal run across the bottom with a jog
  [[0, 255], [60, 255], [100, 255], [150, 255], [160, 265], [230, 265], [240, 255], [300, 255]],

  // Left vertical, tees into the bundle's outer lines (joined by a BRIDGE under the middle)
  [[60, 0], [60, 45], [60, 90], [75, 105], [75, 140]],
  [[75, 160], [75, 200], [60, 215], [60, 255], [60, 300]],

  // Center vertical: tees into the bundle's outer lines (BRIDGE under the middle), branch at the bottom
  [[150, 0], [150, 55], [150, 125]],
  [[150, 145], [150, 200], [150, 255], [150, 300]],
  [[150, 200], [165, 185], [200, 185], [240, 185]],

  // Right vertical: tees into the bundle's outer lines (BRIDGE under the middle)
  [[240, 0], [240, 45], [240, 110], [240, 140]],
  [[240, 160], [240, 185], [240, 255], [240, 300]],

  // Dead-end stubs (end in vias) for density variation
  [[30, 45], [30, 20]],
  [[120, 55], [120, 85], [105, 100]],
  [[240, 110], [270, 110], [280, 100]],
  [[100, 255], [100, 225], [115, 210]],
  [[75, 200], [40, 200], [30, 190]],
  [[200, 185], [200, 215], [215, 230]],
];

/**
 * Layer hops: each vertical joins the bundle's outer lines at vias and passes
 * under the (isolated) middle line on another layer, drawn faint and dashed.
 * Walkable like any edge. Without these, the full-width bundle would wall off
 * vertical travel.
 */
export const BRIDGES: Array<[Point, Point]> = [
  [[75, 140], [75, 160]],
  [[150, 125], [150, 145]],
  [[240, 140], [240, 160]],
];

export interface Node {
  x: number;
  y: number;
  key: string;
  neighbors: string[];
}

export function nodeKey(x: number, y: number): string {
  return `${x},${y}`;
}

export interface Graph {
  nodes: Map<string, Node>;
  size: number;
}

/** Build an undirected graph from TRACES and BRIDGES. Pure; safe to call at module load. */
export function buildGraph(): Graph {
  const nodes = new Map<string, Node>();
  const get = (x: number, y: number): Node => {
    const key = nodeKey(x, y);
    let n = nodes.get(key);
    if (!n) {
      n = { x, y, key, neighbors: [] };
      nodes.set(key, n);
    }
    return n;
  };
  const link = (a: Node, b: Node) => {
    if (!a.neighbors.includes(b.key)) a.neighbors.push(b.key);
    if (!b.neighbors.includes(a.key)) b.neighbors.push(a.key);
  };

  for (const trace of TRACES) {
    for (let i = 1; i < trace.length; i++) {
      link(get(...trace[i - 1]), get(...trace[i]));
    }
  }
  for (const [a, b] of BRIDGES) link(get(...a), get(...b));
  return { nodes, size: TILE_SIZE };
}

export function isPort(n: { x: number; y: number }): boolean {
  return n.x === 0 || n.y === 0 || n.x === TILE_SIZE || n.y === TILE_SIZE;
}

/**
 * Validate the tiling rule: every edge port has a mate on the opposite edge.
 * Returns a list of problems (empty when valid).
 */
export function validateTiling(graph: Graph): string[] {
  const problems: string[] = [];
  for (const n of graph.nodes.values()) {
    if (!isPort(n)) continue;
    if ((n.x === 0 || n.x === TILE_SIZE) && (n.y === 0 || n.y === TILE_SIZE)) {
      problems.push(`corner port at ${n.key} is not supported`);
      continue;
    }
    const mate =
      n.x === 0 ? nodeKey(TILE_SIZE, n.y)
      : n.x === TILE_SIZE ? nodeKey(0, n.y)
      : n.y === 0 ? nodeKey(n.x, TILE_SIZE)
      : nodeKey(n.x, 0);
    if (!graph.nodes.has(mate)) problems.push(`port ${n.key} has no mate at ${mate}`);
  }
  return problems;
}

/**
 * Keys of every node reachable from `startKey`, following tile ports into
 * their mates. Used to keep pulses on the main network rather than on
 * decorative isolated traces (e.g. the middle line of the bundle).
 */
export function connectedKeys(graph: Graph, startKey: string): Set<string> {
  const seen = new Set<string>();
  const stack = [startKey];
  while (stack.length) {
    const key = stack.pop()!;
    if (seen.has(key)) continue;
    const n = graph.nodes.get(key);
    if (!n) continue;
    seen.add(key);
    stack.push(...n.neighbors);
    if (n.x === 0) stack.push(nodeKey(TILE_SIZE, n.y));
    else if (n.x === TILE_SIZE) stack.push(nodeKey(0, n.y));
    if (n.y === 0) stack.push(nodeKey(n.x, TILE_SIZE));
    else if (n.y === TILE_SIZE) stack.push(nodeKey(n.x, 0));
  }
  return seen;
}

/** Keys of the largest connected network in the tile. */
export function mainNetworkKeys(graph: Graph): Set<string> {
  let best = new Set<string>();
  for (const key of graph.nodes.keys()) {
    if (best.has(key)) continue;
    const comp = connectedKeys(graph, key);
    if (comp.size > best.size) best = comp;
  }
  return best;
}
